    internal static class CpuTemperatureSetupStateMapper
    {
        /// <summary>
        /// Maps a <see cref="PawnIoSetupResult"/> (plus execution policy and
        /// current availability) to a <see cref="CpuTemperatureSetupState"/>
        /// for UI presentation.
        /// </summary>
        public static CpuTemperatureSetupState FromSetupResult(
            PawnIoSetupResult? result,
            bool executionEnabled,
            bool currentlyAvailable)
        {
            var now = DateTimeOffset.UtcNow;

            if (!executionEnabled)
            {
                return new CpuTemperatureSetupState(
                    CpuTempSetupPresentationState.SetupNotEnabled,
                    "Setup is not enabled in this candidate.",
                    CanRetry: false,
                    now);
            }

            if (currentlyAvailable)
            {
                return new CpuTemperatureSetupState(
                    CpuTempSetupPresentationState.Available,
                    "CPU temperature is available.",
                    CanRetry: false,
                    now);
            }

            if (result is null)
            {
                return new CpuTemperatureSetupState(
                    CpuTempSetupPresentationState.CheckingSupport,
                    "Checking support...",
                    CanRetry: false,
                    now);
            }

            // RebootRequired takes precedence over success states.
        if (result.RebootRequired && (result.Outcome == PawnIoSetupOutcome.Success || result.Outcome == PawnIoSetupOutcome.AlreadyConfigured))
        {
            return new CpuTemperatureSetupState(
                CpuTempSetupPresentationState.RestartRequired,
                "Setup complete. A restart is required for changes to take effect.",
                CanRetry: false,
                now);
        }

        return result.Outcome switch
        {
            PawnIoSetupOutcome.NotStarted => new CpuTemperatureSetupState(
                CpuTempSetupPresentationState.SetupRequired,
                "Set up CPU temperature to enable this reading.",
                CanRetry: true,
                now),

            PawnIoSetupOutcome.InProgress => new CpuTemperatureSetupState(
                CpuTempSetupPresentationState.SetupInProgress,
                "Setup is in progress...",
                CanRetry: false,
                now),

            PawnIoSetupOutcome.Success => new CpuTemperatureSetupState(
                CpuTempSetupPresentationState.SetupComplete,
                "Setup complete.",
                CanRetry: false,
                now),

            PawnIoSetupOutcome.AlreadyConfigured => new CpuTemperatureSetupState(
                CpuTempSetupPresentationState.Available,
                "CPU temperature is available.",
                CanRetry: false,
                now),

            PawnIoSetupOutcome.Cancelled => new CpuTemperatureSetupState(
                CpuTempSetupPresentationState.SetupCancelled,
                "Setup was cancelled.",
                CanRetry: true,
                now),

            PawnIoSetupOutcome.DependencyInstalledSensorUnavailable => new CpuTemperatureSetupState(
                CpuTempSetupPresentationState.DependencyInstalledSensorUnavailable,
                "PawnIO is installed but CPU temperature sensors are not available. A restart may be required.",
                CanRetry: true,
                now),

            PawnIoSetupOutcome.VerificationFailed
            or PawnIoSetupOutcome.DownloadFailed
            or PawnIoSetupOutcome.LaunchFailed
            or PawnIoSetupOutcome.DependencyStillMissing => new CpuTemperatureSetupState(
                CpuTempSetupPresentationState.SetupFailed,
                BuildFailureDetail(result.Outcome, result.FailureStage),
                CanRetry: true,
                now),

            _ => new CpuTemperatureSetupState(
                CpuTempSetupPresentationState.CheckingSupport,
                "Checking support...",
                CanRetry: false,
                now),
