    /// <summary>
    /// Builds a human-readable failure detail using the structured
    /// <see cref="PawnIoSetupOutcome.FailureStage"/> when available,
    /// falling back to the outcome name.
    /// </summary>
    private static string BuildFailureDetail(PawnIoSetupOutcome outcome, PawnIoSetupFailureStage? stage)
    {
        var stageText = stage.HasValue
            ? stage.Value switch
            {
                PawnIoSetupFailureStage.Download => "during download",
                PawnIoSetupFailureStage.Verification => "during verification",
                PawnIoSetupFailureStage.Launch => "during launch",
                PawnIoSetupFailureStage.PostInstallCheck => "during post-install check",
                _ => null
            }
            : null;

        return stageText is not null
            ? $"Setup failed {stageText}."
            : $"Setup failed: {outcome}.";
    }
